local InstancePathManager = require(script.Parent.Parent.Parent.Core.InstancePathManager)
local XpCallHelper = require(script.Parent.Parent.Parent.Core.DependencyInjection.XpCallHelper)

local LuaType = {}
LuaType.__index = LuaType

function LuaType.new(
	fullname,
	config: {
		FilePath: string,
		Parameters: { any },
		Name: string?,
		Context: string?,
		Ctor: string?,
		IsOperation: boolean?,
	}?
)
	local self = setmetatable({}, LuaType)
	config = config or {}
	self.FullName = fullname
	self.__FilePath = config.FilePath
	self.__Parameters = config.Parameters or {}
	self.Name = config.Name
	self.__Context = config.Context
	self.__OnlyDefine = config.OnlyDefine
	self.__Ctor = config.Ctor or "init"
	self.__LifeTime = config.LifeTime
	self.__IsOperation = config.IsOperation or false

	self.__ParsedParameters = {}
	for i, parameter in ipairs(self.__Parameters) do
		self.__ParsedParameters[i] = { ParameterType = { FullName = parameter } }
	end

	self.__Constructors = {
		{
			GetParameters = function()
				return self.__ParsedParameters
			end,
			luaCtor = function(...)
				local instance = InstancePathManager.GetInstanceByPathFromCache(self.FullName)
				if not instance then
					error("Unable to create instance for type: " .. self.FullName)
				end
				if not instance:IsA("ModuleScript") then
					error("Unable to create instance for type: " .. self.FullName)
				end
				local module = require(instance)

				if self.__Ctor == "new" then
					module = XpCallHelper.call(function(...)
						return module.new(...)
					end, 0, `error on resolve service '{self.FullName}' \n`, ...)
				elseif type(module) == "function" then
					module = XpCallHelper.call(function(...)
						return module(...)
					end, 0, `error on resolve service '{self.FullName}' \n`, ...)
				else
					if module.Init then
						XpCallHelper.call(function(...)
							module.Init(...)
							return module
						end, 0, `error on resolve service '{self.FullName}' \n`, ...)
					end
				end

				return module
			end,
		},
	}
	return self
end

function LuaType:GetGenericArguments()
	error("未实现")
end

function LuaType:GetConstructors()
	return self.__Constructors
end

return LuaType
